print("[2] اجرای migrate...")
import subprocess
r = subprocess.run([sys.executable, "manage.py", "migrate", "--verbosity=0"],
                   capture_output=True, text=True)
if r.returncode == 0:
    print("  OK - migrate موفق")
else:
    lines = (r.stdout + r.stderr).strip().split("\n")
    for line in lines[-6:]:
        if line.strip(): print(" ", line)
    sys.exit(1)

